INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'History', 'Unit 5', 'Molarum Grade 10 — History Unit 5: Global and Regional Developments Since 1945', 'Source-grounded Molarum Grade 10 History questions for Unit 5: Global and Regional Developments Since 1945.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('d7989a2d-0f91-462b-84d2-a55d4a0b75c5'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'In what year was the United Nations established?', '1945', 'The textbook states that the United Nations was established in 1945.', 0),('803bbbfc-1fa2-4ac4-8212-21fa207ed9e1'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'What organization was the predecessor of the United Nations?', 'League of Nations', 'The source identifies the League of Nations as the predecessor of the United Nations.', 1),('3cac09bc-4533-40aa-8320-31b47a6d8084'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'Which language was added as an official UN language in 1973?', 'Arabic', 'The textbook says Arabic was added to the UN''s official languages in 1973.', 2),('01045c46-2313-4346-837a-9f7f1594705d'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'Which UN organ has one vote for each member nation?', 'General Assembly', 'The General Assembly consists of representatives of all member nations and gives each nation one vote.', 3),('3f92d848-26f6-4196-8678-f64c0f1ef1e1'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'Which UN organ is charged with maintaining peace and security among countries?', 'Security Council', 'The source states that the Security Council is charged with maintaining peace and security.', 4),('605ba98e-3a3f-4764-825e-d3be72a3feb6'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'Where is the International Court of Justice seated?', 'The Hague, Netherlands', 'The textbook identifies The Hague in the Netherlands as the seat of the International Court of Justice.', 5),('d1bf41be-bfdb-47ae-829b-1e91b2090311'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'Which two states emerged as superpowers after World War II according to the textbook?', 'USA and USSR', 'The Second World War resulted in the emergence of the USA and the USSR as superpowers.', 6),('cc3dfe85-3f4a-4379-82a9-6ed7141e0cb6'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'What term described the political and ideological barrier separating the Soviet bloc from the West?', 'Iron Curtain', 'The source defines the Iron Curtain as the barrier erected by the Soviet Union to seal off itself and its satellite states.', 7),('8490a345-625a-4553-8aa2-1c1b1a46b957'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'Which Cold War strategy involved collecting intelligence through spies and secret agents?', 'Espionage', 'The textbook defines espionage as collecting intelligence and information through spies and secret agents.', 8),('bcde2dcb-3b46-4c4f-8bad-4c7dcce30e71'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'What was the central purpose of the Truman Doctrine?', 'To stop the spread of communism', 'The Truman Doctrine committed the United States to stopping communism''s spread.', 9),('5737b5df-8176-4f2b-8a19-63d922e8f868'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'What was the Marshall Plan also called in the textbook?', 'European recovery program', 'George Marshall''s 1947 policy is described as the European recovery program, often called the Marshall Plan.', 10),('3b01105b-8e67-48a8-8d2a-9dfcccf60cb6'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'What action supplied West Berlin during the Berlin Blockade?', 'Berlin airlift', 'The United States and other nations launched the Berlin airlift to supply West Berlin.', 11),('400f10c4-1bca-443c-8076-e21e1c48e991'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'Which military alliance was founded for the United States and Western Europe in April 1949?', 'NATO', 'The source says the North Atlantic Treaty Organization was founded in April 1949.', 12),('0bd52984-0c13-4a27-8f03-32a171d447b8'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'Who led the Chinese Communist Party during the Chinese civil war described in the textbook?', 'Mao Tse Tung', 'The textbook identifies Mao Tse Tung, also called Mao Zedong, as leader of the Chinese Communist Party.', 13),('e9ebbd31-0aa8-4f78-886e-d4a6cf0caa4e'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'Which parallel divided Soviet-occupied northern Korea from US-occupied southern Korea after World War II?', '38th parallel', 'The source says the dividing line in Korea was the 38th parallel of latitude.', 14),('84d31d56-17d8-4376-8132-4f9a1402add0'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'What organization did Ho Chi Minh establish during the First Indochina War?', 'Viet Minh', 'Ho Chi Minh established the Viet Minh, a Vietnamese communist independence movement.', 15),('d80139ff-409c-48e4-87dd-d013d242ad7c'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'What was the main position of Non-Aligned Movement states during the Cold War?', 'They did not formally align with either the USA or USSR', 'NAM was formed by states seeking to remain independent rather than formally align with either superpower.', 16),('68a65a95-1690-47c3-8468-0ac9814d9523'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'What British statement supported the establishment of a Jewish homeland in Palestine in 1917?', 'Balfour Declaration', 'The source identifies the 1917 British support for a Jewish homeland as the Balfour Declaration.', 17),('090e3c58-54b4-4bba-83dc-6fb9cdd0553a'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'Who announced the nationalization of the Suez Canal Company in 1956?', 'Gamal Abdel Nasser', 'The textbook states that Gamal Abdel Nasser announced the nationalization of the Suez Canal Company.', 18),('140cc982-f0eb-4713-884f-c6bee3634922'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'multiple_choice', 'What Soviet reform meant openness or publicity?', 'Glasnost', 'Glasnost is defined in the source as openness or publicity.', 19),('0f9759e2-23ef-43f9-8b79-40a5b86a6bbd'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'true_false', 'Permanent members of the UN Security Council can veto Council decisions.', 'True', 'The source states that the five permanent Security Council members have veto power.', 20),('aaf8b311-e85b-4c60-808b-126eb2a5915a'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'true_false', 'The Cold War involved a large-scale direct war between the USA and the USSR.', 'False', 'It was called the Cold War because the two nations did not fight a large-scale direct war against each other.', 21),('dcadac14-e228-4317-8448-2acfa4ec81eb'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'true_false', 'Vietnamization aimed to reduce American involvement by transferring military responsibilities to South Vietnam.', 'True', 'The source defines Vietnamization as transferring military responsibilities to South Vietnam to reduce American involvement.', 22),('9289c2cb-7411-4af2-873c-1c545c3a987d'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'true_false', 'Perestroika aimed to allow private ownership of some businesses in the USSR.', 'True', 'The textbook describes perestroika as restructuring that allowed private ownership of some businesses.', 23),('a8cf1e79-e77c-4a8a-8064-4b0cc624f7e7'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'State one UN principle concerning disputes between member states.', 'Disputes are to be settled through peaceful means.', 'The source lists peaceful settlement of disputes as an essential UN principle.', 24),('a55041a4-ad31-4764-8e1b-70cb797ba4bb'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'Name one country that Truman sought to assist against communist attack in 1947.', 'Greece or Turkey.', 'Truman requested assistance for Greece and Turkey against communist attack.', 25),('fac67948-e354-4621-8569-277595cdad48'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'Give one stated aim of the Marshall Plan.', 'Stop the spread of communism, help European economies recover, or provide a market for American goods.', 'The textbook lists these political and economic aims of the Marshall Plan.', 26),('6337cb99-29f0-4f8d-8772-5bdf7564a25f'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'State one consequence of the Berlin Blockade listed in the textbook.', 'It worsened the Cold War, created East and West Germany, led to NATO and the Warsaw Pact, or intensified the arms race.', 'The source lists each of these as consequences of the Berlin Blockade.', 27),('6ca4b1ef-880f-41b5-8976-acbcc5c2f0ad'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'Give one result of the Korean War stated in the textbook.', 'South Korea was saved from communism, millions became refugees, China became a major power in Asia, or American protection for Taiwan increased.', 'The source lists these political and humanitarian results of the Korean War.', 28),('37c5808c-56e9-4281-8a36-2fd09a3f175d'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'State one goal in the Havana Declaration for the Non-Aligned Movement.', 'To ensure the national independence, sovereignty, territorial integrity, or security of non-aligned countries against imperialism, colonialism, neocolonialism, racism, and foreign subjugation.', 'The Havana Declaration listed these protections and struggles as NAM purposes.', 29),('d1d1f864-e5d2-4548-866b-94653422d483'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'Why did the Arab world call the 1948 war Nakba according to the textbook?', 'Because it caused a large number of refugees and displaced persons.', 'The source says the war was called Nakba, or Catastrophe, because of the many refugees and displaced people.', 30),('321b4e96-1532-4766-8801-138a6284ac6d'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'State one feature of the 1989 changes in Eastern Europe described in the textbook.', 'Nationalist movements brought regime change, communist regimes were overthrown, or the changes were peaceful except in Romania where the revolution was violent.', 'The textbook describes 1989 nationalist movements and the collapse of communist regimes across Eastern Europe.', 31),('2fb71ce0-bc27-4974-89d2-a6a78f3ef781'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'How many nations signed the UN Charter in San Francisco in June 1945?', '50', 'The textbook says 50 nations represented in San Francisco signed the Charter on 26 June 1945.', 32),('0c3b656b-2def-4a87-8868-107b7465990e'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'How many permanent members are on the UN Security Council according to the textbook?', '5', 'The source lists five permanent members of the Security Council.', 33),('4d11a9fa-1698-4b82-874f-6f1663da59a0'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'In what year did the Berlin Blockade begin?', '1948', 'Stalin imposed the Berlin Blockade in June 1948.', 34),('13e19ae1-d70f-474b-813f-ee96fae41961'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'In what year was the Warsaw Pact formed?', '1955', 'The textbook dates the formation of the Warsaw Pact in Warsaw to May 1955.', 35),('941d0e60-ae6b-48a6-8531-91ae39bdce0d'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'In what year was the People''s Republic of China formed by the Chinese Communists?', '1949', 'The source says the People''s Republic of China was formed in October 1949.', 36),('f5130a76-e1ea-41f1-8737-1b6e1899f382'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'On what date was the First Indochina War''s Viet Minh victory at Dien Bien Phu given in the textbook?', '7 May 1954', 'The textbook dates the French defeat by the Viet Minh at Dien Bien Phu to 7 May 1954.', 37),('75c43ebc-d4be-44d8-8200-6ca55e7ca2bb'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'In what year did the first NAM Conference take place in Belgrade?', '1961', 'The first Non-Aligned Movement Conference took place in Belgrade in September 1961.', 38),('a95a9cd1-e851-4591-8308-0c68963bb9d5'::uuid, '23b2ca1c-01e7-434b-871a-01866e1c904b'::uuid, 'fill_blank', 'In what year did fifteen sovereign states emerge from the collapse of the USSR?', '1991', 'The source states that fifteen sovereign states emerged from the USSR''s collapse in 1991.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
